-- Two additions to the RLS demographic battery from 0047, both places where
-- this site's readers are not Pew's sample.
--
-- 1. Country of residence. The RLS has no counterpart - it surveys U.S.
--    adults, so residence is assumed. Readers here are not all American,
--    and recording "not the U.S." beats recording a blank state. ISO 3166-1
--    alpha-2; the exact membership (253 codes) lives in demographics.ts,
--    generated by scripts/gen-country-options.mjs.
--
-- 2. The 2010s and 2020s birth cohorts. Pew's BIRTHDECADE stops at the
--    2000s because it surveys adults. This site's own floor is 13+ (COPPA,
--    migration 0037), which the 2010s are already inside of. Neither cohort
--    has an RLS code, so rows carrying one simply fall outside a comparison
--    with Pew's national numbers.
--
-- Where 0047 could add its columns with plain `add column if not exists`, a
-- widened value list means dropping and rebuilding the check constraint.
-- Both are named by Postgres's default <table>_<column>_check convention,
-- confirmed against the live database before writing this.

alter table public.profiles
  -- Paired with us_state: a non-US country forces us_state to null, which
  -- validateDemographics enforces before any write. Not a database-level
  -- constraint, because rows recorded before this column existed carry a
  -- state and no country, and they are older rather than wrong.
  add column if not exists country text check (country ~ '^[A-Z]{2}$');

alter table public.evangelical_quiz_runs
  add column if not exists country text check (country ~ '^[A-Z]{2}$');

alter table public.profiles
  drop constraint if exists profiles_birth_decade_check;
alter table public.profiles
  add constraint profiles_birth_decade_check check (birth_decade in
    ('1940s_or_earlier','1950s','1960s','1970s','1980s','1990s','2000s','2010s','2020s',
     'prefer_not_to_say'));

alter table public.evangelical_quiz_runs
  drop constraint if exists evangelical_quiz_runs_birth_decade_check;
alter table public.evangelical_quiz_runs
  add constraint evangelical_quiz_runs_birth_decade_check check (birth_decade in
    ('1940s_or_earlier','1950s','1960s','1970s','1980s','1990s','2000s','2010s','2020s',
     'prefer_not_to_say'));
